create extension if not exists vector with schema extensions;
create type public.app_role as enum ('owner','super_admin','admin','hr','sales','employee','project_member','research_member','guest');
create type public.application_status as enum ('pending','approved','rejected');
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text not null,email text not null,phone text,department text,position text,locale text not null default 'ar',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid references public.profiles on delete cascade,role public.app_role not null,granted_by uuid references public.profiles,created_at timestamptz not null default now(),primary key(user_id,role));
create table public.applications(id uuid primary key default gen_random_uuid(),full_name text not null,email text not null,phone text not null,organization text not null,title text not null,account_type public.app_role not null,project_or_research text,join_reason text not null,cover_letter text not null,cv_path text,status public.application_status not null default 'pending',internal_rejection_reason text,decided_by uuid references public.profiles,decided_at timestamptz,created_at timestamptz not null default now(),check(status<>'rejected' or internal_rejection_reason is not null));
create table public.projects(id uuid primary key default gen_random_uuid(),name text not null,type text not null check(type in('internal','client','research','product','competition')),manager_id uuid references public.profiles,client_id uuid,status text not null default 'planning',budget numeric(14,2),github_repo text,visibility text not null default 'private',created_at timestamptz not null default now());
create table public.project_members(project_id uuid references public.projects on delete cascade,user_id uuid references public.profiles on delete cascade,member_role text not null default 'member',primary key(project_id,user_id));
create table public.research(id uuid primary key default gen_random_uuid(),title text not null,abstract text,status text not null default 'proposal',supervisor_id uuid references public.profiles,is_public boolean not null default false,timeline jsonb not null default '{}',ethics_status text,doi text,conference text,created_at timestamptz not null default now());
create table public.research_members(research_id uuid references public.research on delete cascade,user_id uuid references public.profiles on delete cascade,member_role text not null default 'researcher',primary key(research_id,user_id));
create table public.tasks(id uuid primary key default gen_random_uuid(),title text not null,description text,status text not null default 'todo',priority int not null default 2 check(priority between 0 and 4),assignee_id uuid references public.profiles,project_id uuid references public.projects on delete cascade,research_id uuid references public.research on delete cascade,due_at timestamptz,created_by uuid references public.profiles,created_at timestamptz not null default now());
create table public.timesheets(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles,task_id uuid references public.tasks,minutes int not null check(minutes>0),work_date date not null,notes text,created_at timestamptz not null default now());
create table public.crm_contacts(id uuid primary key default gen_random_uuid(),name text not null,email text,phone text,company text,stage text not null default 'lead',owner_id uuid references public.profiles,value numeric(14,2),created_at timestamptz not null default now());
create table public.agents(id text primary key,name text not null,status text not null default 'idle',model text not null default 'gemma4:12b',host text not null default 'ai-lap',approval_level int not null check(approval_level between 0 and 4),permissions jsonb not null default '[]',configuration jsonb not null default '{}',last_heartbeat timestamptz);
create table public.agent_runs(id uuid primary key default gen_random_uuid(),agent_id text references public.agents,task_id uuid references public.tasks,status text not null,prompt_hash text,latency_ms int,token_usage int,error text,logs jsonb not null default '[]',created_at timestamptz not null default now());
create table public.memories(id uuid primary key default gen_random_uuid(),scope text not null check(scope in('user','project','department','company','agent')),scope_id text not null,content text not null,embedding extensions.vector(768),classification text not null default 'internal',created_at timestamptz not null default now());
create table public.audit_logs(id bigint generated always as identity primary key,actor_id uuid,action text not null,table_name text not null,record_id text,old_data jsonb,new_data jsonb,ip inet,created_at timestamptz not null default now());
create or replace function public.has_role(wanted public.app_role) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.user_roles where user_id=auth.uid() and role=wanted)$$;
create or replace function public.is_admin() returns boolean language sql stable as $$select public.has_role('owner') or public.has_role('super_admin') or public.has_role('admin')$$;
create or replace function public.audit_row() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.audit_logs(actor_id,action,table_name,record_id,old_data,new_data) values(auth.uid(),tg_op,tg_table_name,coalesce(new.id,old.id)::text,to_jsonb(old),to_jsonb(new));return coalesce(new,old);end$$;
do $$declare t text;begin foreach t in array array['profiles','user_roles','applications','projects','project_members','research','research_members','tasks','timesheets','crm_contacts','agents','agent_runs','memories'] loop execute format('alter table public.%I enable row level security',t);execute format('create trigger audit_%I after insert or update or delete on public.%I for each row execute function public.audit_row()',t,t);end loop;end$$;
alter table public.audit_logs enable row level security;
create policy profile_self on public.profiles for select using(id=auth.uid() or public.is_admin() or public.has_role('hr'));
create policy roles_admin_read on public.user_roles for select using(user_id=auth.uid() or public.is_admin() or public.has_role('hr'));
create policy roles_owner_write on public.user_roles for all using(public.has_role('owner') or public.has_role('super_admin')) with check(public.has_role('owner') or public.has_role('super_admin'));
create policy applications_public_insert on public.applications for insert to anon,authenticated with check(status='pending' and decided_by is null);
create policy applications_staff_read on public.applications for select to authenticated using(public.is_admin() or public.has_role('hr'));
create policy applications_first_decision on public.applications for update to authenticated using(status='pending' and (public.is_admin() or public.has_role('hr'))) with check(status in('approved','rejected') and decided_by=auth.uid() and decided_at is not null);
create policy project_member_read on public.projects for select using(public.is_admin() or exists(select 1 from public.project_members m where m.project_id=id and m.user_id=auth.uid()));
create policy research_visibility on public.research for select using(is_public or public.is_admin() or exists(select 1 from public.research_members m where m.research_id=id and m.user_id=auth.uid()));
create policy task_scope_read on public.tasks for select using(public.is_admin() or assignee_id=auth.uid() or exists(select 1 from public.project_members m where m.project_id=tasks.project_id and m.user_id=auth.uid()) or exists(select 1 from public.research_members m where m.research_id=tasks.research_id and m.user_id=auth.uid()));
create policy own_timesheets on public.timesheets for all using(user_id=auth.uid() or public.is_admin() or public.has_role('hr')) with check(user_id=auth.uid() or public.is_admin());
create policy crm_staff on public.crm_contacts for all using(public.is_admin() or public.has_role('hr') or public.has_role('sales')) with check(public.is_admin() or public.has_role('hr') or public.has_role('sales'));
create policy agents_admin on public.agents for select using(public.is_admin());create policy runs_admin on public.agent_runs for select using(public.is_admin());
create policy audit_admin_read on public.audit_logs for select using(public.has_role('owner') or public.has_role('super_admin') or public.has_role('admin'));
insert into public.agents(id,name,approval_level) values('ceo','CEO / Orchestrator',3),('operations','Operations',1),('marketing','Marketing',2),('content','Content / Social',2),('sales','Sales / CRM',2),('analytics','Analytics',1),('knowledge','Knowledge',1),('hr','HR',3),('finance','Finance',3),('support','Customer Support',2),('competitor','Competitor Intelligence',1);
